// FactFlip's question bank — kept entirely separate from game logic so it
// can be expanded independently. Questions are grouped into difficulty
// tiers (1 = easiest), with a curated starter pool for the first five levels.
//
// Hand-written statements live in this file; large templated batches
// generated from verified reference tables (world capitals, currencies,
// chemical elements, etc.) live in factflipGenerator.ts and are merged in
// below — see that file to add a new generated category.

import { GENERATED_QUESTIONS } from "./factflipGenerator";

export type FactFlipCategory =
  | "indian"
  | "science"
  | "geography"
  | "history"
  | "sports"
  | "animals"
  | "body"
  | "space"
  | "everyday"
  | "world";

export interface FactFlipQuestion {
  id: string;
  tier: number;
  category: FactFlipCategory;
  statement: string;
  answer: boolean;
  explanation: string;
  starter?: true;
}

type RawQuestion = [
  category: FactFlipCategory,
  statement: string,
  answer: boolean,
  explanation: string,
  starter?: true,
];

function buildTier(tier: number, raw: RawQuestion[]): FactFlipQuestion[] {
  return raw.map(([category, statement, answer, explanation, starter], i) => ({
    id: `t${tier}-${String(i + 1).padStart(2, "0")}`,
    tier,
    category,
    statement,
    answer,
    explanation,
    ...(starter && { starter }),
  }));
}

